param([string]$Results='Temp/MillionScaleExecution/member-order',[switch]$TargetedOnly)
$ErrorActionPreference='Stop';$root=Split-Path $PSScriptRoot -Parent;. (Join-Path $PSScriptRoot 'ProjectLayout.ps1');$out=Join-Path $root $Results;if(Test-Path -LiteralPath $out){throw 'Fresh output required'};New-Item -ItemType Directory -Path $out|Out-Null
$frozen=@{};foreach($relative in @('Core/CityCoreSave.cs','Core/CityEntities.cs','Industry/CityCoreIndustrySession.cs')){$name=[IO.Path]::GetFileName($relative);$path=Join-Path $out $name;$source=& git -C $root show ('30ede55:Assets/Scripts/Runtime/Simulation/'+$relative);if($LASTEXITCODE -ne 0){throw 'Frozen source unavailable'};[IO.File]::WriteAllLines($path,$source);$frozen[$name]=$path}
$oldSave=Join-Path (Split-Path $root -Parent) 'test/Temp/CityScenarios/regenerated30000-20261017/city.hcity';$newSave=$null;if(!$TargetedOnly){$newSave=Export-CityMemberOrderFixture $root $oldSave $out}
foreach($version in @('old','new')){$overrides=@{};$defines='ORDER_PERSISTED;RESIDENT_STATE';$save=$newSave;if($version -eq 'old'){$overrides=$frozen;$defines='';$save=$oldSave};$cases=@('order','state');if(!$TargetedOnly){$cases+='growth'};foreach($case in $cases){$dir=Join-Path $out ($version+'/'+$case);New-Item -ItemType Directory -Path $dir -Force|Out-Null;$entry=Join-Path $PSScriptRoot $(if($case -eq 'order'){'Diagnostics/CityMemberOrderChecks.cs'}elseif($case -eq 'state'){'Diagnostics/CityResidentStateChecks.cs'}else{'Diagnostics/CityGrowthCandidateChecks.cs'});$entry=New-CityOrderWitnessEntry $root $entry $dir;$binary=Build-CityDotNetHost -ProjectRoot $root -OutputDirectory $dir -Entry $entry -Defines $defines -SourceOverrides $overrides;if($case -ne 'growth'){& dotnet $binary $dir}else{& dotnet $binary $save $dir};if($LASTEXITCODE -ne 0){throw ($version+' '+$case+' failed')}}}
if(!$TargetedOnly -and [IO.File]::ReadAllText((Join-Path $out 'old/growth/states.csv')) -cne [IO.File]::ReadAllText((Join-Path $out 'new/growth/states.csv'))){throw 'Full business/transport/order witness differs'}
$old=Import-Csv (Join-Path $out 'old/order/order-results.csv');$new=Import-Csv (Join-Path $out 'new/order/order-results.csv');foreach($row in $new){if($row.equal -ne 'True'){throw 'Current warm/cold states differ'}};foreach($row in $old){$match=$new|Where-Object case -eq $row.case;if($match.warm_sha256 -cne $row.warm_sha256){throw 'Original warm execution behavior changed'}}
Write-Output 'PASS persisted order restores original warm behavior, cold continuity, and all witnessed facts; no runtime v17 reader'

foreach($relative in @('states.csv','requests.csv')){if([IO.File]::ReadAllText((Join-Path $out ('old/state/'+$relative))) -cne [IO.File]::ReadAllText((Join-Path $out ('new/state/'+$relative)))){throw 'Non-moved full state/request witness differs'}}
